CREATE OR REPLACE FUNCTION public.ppm_validar_filho() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_TABLE_NAME='projeto_subelementos' THEN IF NOT EXISTS(SELECT 1 FROM public.projeto_elementos WHERE id=NEW.elemento_id AND projeto_id=NEW.projeto_id) THEN RAISE EXCEPTION 'Elemento e projeto incompatíveis'; END IF; ELSIF TG_TABLE_NAME='projeto_atualizacoes' THEN IF length(trim(NEW.texto)) NOT BETWEEN 2 AND 2000 THEN RAISE EXCEPTION 'Texto inválido'; END IF; IF NEW.alvo_tipo='projeto' AND NEW.alvo_id<>NEW.projeto_id OR NEW.alvo_tipo='elemento' AND NOT EXISTS(SELECT 1 FROM public.projeto_elementos WHERE id=NEW.alvo_id AND projeto_id=NEW.projeto_id) OR NEW.alvo_tipo='subelemento' AND NOT EXISTS(SELECT 1 FROM public.projeto_subelementos WHERE id=NEW.alvo_id AND projeto_id=NEW.projeto_id) OR NEW.alvo_tipo NOT IN ('projeto','elemento','subelemento') THEN RAISE EXCEPTION 'Contexto inválido'; END IF; END IF; RETURN NEW; END $$;